/option><option value="product">استفسار منتج</option><option value="other">استفسار عام</option></select></label><label>تفاصيل الطلب<textarea name="message" required maxlength="5000" rows="6"></textarea></label><button class="btn">إرسال الطلب</button></form><?php else:?><section class="pagehead"><h1><?=e($title)?></h1><p>أعمال وخدمات ومنتجات تُدار بالكامل من لوحة التحكم.</p></section><div class="cards"><?php foreach($items as $item):?><article class="card"><?php if($item['image_url']):?><img loading="lazy" src="<?=e($item['image_url'])?>" alt=""><?php endif;?><div class="cardbody"><span class="eyebrow"><?=e($title)?></span><h2><?=e($item['title'])?></h2><p><?=nl2br(e($item['description']))?></p><?php if($item['price']!==null):?><strong><?=e(number_format((float)$item['price'],2))?> ر.س</strong><?php endif;?><div class="actions"><?php if($item['external_url']):?><a class="btn ghost" rel="noopener noreferrer" target="_blank" href="<?=e($item['external_url'])?>">عرض التفاصيل</a><?php endif;?><a class="btn" href="?page=contact">استفسر الآن</a></div></div></article><?php endforeach;?></div><?php if(!$items):?><div class="empty">سيتم إضافة المحتوى قريبًا من لوحة الإدارة.</div><?php endif;?><?php endif;?></main><footer><div class="wrap">© <?=date('Y')?> مركز أعمالي · جميع الحقوق محفوظة</div></footer><script src="assets/app.js"></script></body></html>